"use server";

/**
 * Marks the whole inbox read.
 *
 * Owner D. Returns the number of rows touched so the bell badge can be updated
 * without a second round trip.
 *
 * Must call (do not reimplement): markAllNotificationsReadSchema, can,
 * getActor, toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import { markAllNotificationsReadSchema } from "@/schemas/notification";
import { markAllRead } from "@/server/services/notification-service";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";

type MarkAllReadInput = { orgId: OrgId };

const run = withAction<typeof markAllNotificationsReadSchema, number>(
  markAllNotificationsReadSchema,
  async (raw, actor) => {
    const input = raw as MarkAllReadInput;

    const allowed = can(actor, "notification:manage", {
      kind: "notification",
      orgId: input.orgId,
      recipientId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("notification:manage");
    }

    const count = await markAllRead(actor, input.orgId);
    revalidateTagged(["notifications"], CACHE_PROFILES.seconds);
    return count;
  },
  { revalidate: ["notifications"], cacheProfile: "seconds" },
);

export async function markAllNotificationsReadAction(
  raw: unknown,
): Promise<ActionResult<number>> {
  return run(raw);
}
"use server";

/**
 * Marks one notification read.
 *
 * Owner D. `notification:read` is granted to every role, but the resource
 * carries `recipientId` — the ownership escalation inside `can()` is what stops
 * one member marking another member's inbox.
 *
 * Must call (do not reimplement): markNotificationReadSchema, can, getActor,
 * toActionResult
 */

import { ForbiddenActionError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { can } from "@/lib/permissions";
import {
  markNotificationReadSchema,
  type MarkNotificationReadInput,
} from "@/schemas/notification";
import { markRead } from "@/server/services/notification-service";
import type { ActionResult } from "@/types/api";
import type { Notification } from "@/types/notification";

const run = withAction<typeof markNotificationReadSchema, Notification>(
  markNotificationReadSchema,
  async (raw, actor) => {
    const input = raw as MarkNotificationReadInput;

    const allowed = can(actor, "notification:read", {
      kind: "notification",
      orgId: input.orgId,
      recipientId: actor.userId,
    });
    if (!allowed) {
      throw new ForbiddenActionError("notification:read");
    }

    const notification = await markRead(actor, input);
    revalidateTagged(["notifications"], CACHE_PROFILES.seconds);
    return notification;
  },
  { revalidate: ["notifications"], cacheProfile: "seconds" },
);

export async function markNotificationReadAction(
  raw: unknown,
): Promise<ActionResult<Notification>> {
  return run(raw);
}
"use server";

/**
 * Updates one notification preference row.
 *
 * Owner D. `digestOnly` is only meaningful while the `digest_email` flag is on
 * for the organization; asking for it otherwise would strand the notification
 * in a digest that never gets sent, so the flag is checked here.
 *
 * Must call (do not reimplement): updateNotificationPreferenceSchema,
 * isEnabled, getActor, toActionResult
 */

import { FeatureUnavailableError } from "@/actions/_lib/action-errors";
import { withAction } from "@/actions/_lib/with-action";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { isEnabled } from "@/lib/feature-flags";
import {
  updateNotificationPreferenceSchema,
  type UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { updatePreference } from "@/server/services/notification-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import type { ActionResult } from "@/types/api";
import type { NotificationPreference } from "@/types/notification";

const run = withAction<
  typeof updateNotificationPreferenceSchema,
  NotificationPreference
>(
  updateNotificationPreferenceSchema,
  async (raw, actor) => {
    const input = raw as UpdateNotificationPreferenceInput;

    const { organization } = await getOrganizationSummary(actor, input.orgId);
    const context = buildFlagContext(actor, organization);

    if (input.digestOnly && !isEnabled("digest_email", context)) {
      throw new FeatureUnavailableError("digest_email");
    }

    const preference = await updatePreference(actor, input);
    revalidateTagged(["notification-preferences"], CACHE_PROFILES.hours);
    return preference;
  },
  { revalidate: ["notification-preferences"], cacheProfile: "hours" },
);

export async function updateNotificationPreferenceAction(
  raw: unknown,
): Promise<ActionResult<NotificationPreference>> {
  return run(raw);
}
/**
 * Wrapper shared by every Server Action: parses with a Zod schema, resolves the
 * `Actor`, maps thrown domain errors to an `AppErrorShape` and revalidates the
 * affected tags.
 *
 * Owner D. Every mutation in `src/actions/**` funnels through here so the four
 * things each one must do — validate, authenticate, translate errors,
 * revalidate — happen in exactly one place.
 *
 * Must call (do not reimplement): getActor, toActionResult, revalidateTagged
 */

import { getActor, requireActorFor } from "@/lib/actor";
import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
import { toActionResult } from "@/lib/errors";
import { getSessionPrincipal } from "@/lib/session";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { ZodType } from "zod";
import { UnauthorizedActionError } from "./action-errors";

/** The body of an action: already-validated input plus the resolved principal. */
export type ActionHandler = (input: unknown, actor: Actor) => Promise<unknown>;

export type ActionOptions = {
  /**
   * When `true` (the default) the organization is taken from the parsed input —
   * either an `orgSlug` or an `orgId` field. When `false` the action does not
   * name an organization and the session's active org is used instead.
   */
  requireOrg?: boolean;
  /** Static cache tags invalidated once the handler resolves. */
  revalidate?: readonly string[];
  /** cacheLife profile handed to `revalidateTag` — required in Next 16. */
  cacheProfile?: string;
};

type OrgBearingInput = { orgSlug?: unknown; orgId?: unknown };

/**
 * Resolves the actor for one action call.
 *
 * `getActor(orgSlug)` is the primary path because most mutations are dispatched
 * from a `[orgSlug]` route; actions whose payload carries the branded `orgId`
 * instead resolve through `requireActorFor()`.
 */
async function resolveActorFor(input: unknown, fromInput: boolean): Promise<Actor> {
  if (fromInput && typeof input === "object" && input !== null) {
    const record = input as OrgBearingInput;
    if (typeof record.orgSlug === "string" && record.orgSlug.length > 0) {
      return getActor(record.orgSlug);
    }
    if (typeof record.orgId === "string" && record.orgId.length > 0) {
      return requireActorFor(record.orgId as OrgId);
    }
  }

  const principal = await getSessionPrincipal();
  if (principal === null || principal.activeOrgId === null) {
    throw new UnauthorizedActionError();
  }
  return requireActorFor(principal.activeOrgId);
}

/** Adds the monotonic token `useActionState` uses to tell two results apart. */
function stamp<T>(result: ActionResult<T>): ActionResult<T> {
  const submittedAt = new Date().toISOString();
  return result.ok
    ? { ok: true, data: result.data, submittedAt }
    : { ok: false, error: result.error, submittedAt };
}

export function withAction<TSchema extends ZodType, TData>(
  schema: TSchema,
  handler: ActionHandler,
  options: ActionOptions = {},
): (raw: unknown) => Promise<ActionResult<TData>> {
  return async function runAction(raw: unknown): Promise<ActionResult<TData>> {
    const parsed = schema.safeParse(raw);
    if (!parsed.success) {
      return stamp(toActionResult(parsed.error));
    }

    try {
      const actor = await resolveActorFor(parsed.data, options.requireOrg !== false);
      const data = (await handler(parsed.data, actor)) as TData;

      const tags = options.revalidate ?? [];
      if (tags.length > 0) {
        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
      }

      return stamp({ ok: true, data });
    } catch (error) {
      return stamp(toActionResult(error));
    }
  };
}
/**
 * Placeholder branded ids for `can()` calls about rows that do not exist yet.
 *
 * `PermissionResource` is a closed discriminated union, so asking "may this
 * actor create an issue in this project?" still has to name an `issueId`. The
 * ownership escalations inside `can()` compare ids for equality, and an empty
 * string never matches a real ULID — so a create check falls through to the
 * role matrix, which is exactly the intent.
 */

import type {
  CommentId,
  IssueId,
  MemberId,
  OrgId,
  ProjectId,
} from "@/types/common";

export const PENDING_ISSUE_ID = "" as IssueId;
export const PENDING_PROJECT_ID = "" as ProjectId;
export const PENDING_COMMENT_ID = "" as CommentId;
export const PENDING_MEMBER_ID = "" as MemberId;

/**
 * Bucket owner for rate limits consumed before any tenant is known — the login
 * and password-reset flows, which are reachable without a session.
 */
export const ANONYMOUS_ORG_ID = "" as OrgId;
/**
 * Notification inbox.
 *
 * Owner D. The list component receives the two mutations as props rather than
 * importing the actions itself — that keeps `src/components/domain` free of any
 * dependency on the action layer.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { NotificationList } from "@/components/domain/notification/notification-list";
import { markAllNotificationsReadAction } from "@/actions/notifications/mark-all-read";
import { markNotificationReadAction } from "@/actions/notifications/mark-read";
