async function notifyAssigned(
  orgId: OrgId,
  issueId: IssueId,
  assigneeId: UserId,
  actorId: UserId | null,
): Promise<void> {
  if (assigneeId === actorId) return;
  const href = await issueHref(orgId, issueId);
  if (href === null) return;
  await notify(orgId, "issue_assigned", [assigneeId], {
    title: "You were assigned an issue",
