    if (payload.assigneeId === null) return;
    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href,
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue) return;
    const href = await issueHref(payload.orgId, payload.issueId);
    if (href === null) return;

    const watchers = [
      issue.authorId,
      ...(issue.assigneeId ? [issue.assigneeId] : []),
    ];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href,
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href,
          actorId: payload.actorId,
        },
      );
    }
  });

  // The owner hears about every new member; the joiner is the event's actor,
  // so `notify` never tells them about themselves.
  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId], {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: payload.userId,
    });
  });

  // One unread alert per resource: further refusals stay quiet until the
  // owner has read it.
  subscribe("billing.limit_exceeded", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    const title = `Plan limit reached: ${RESOURCE_LABELS[payload.resource]}`;

    const pending = await notificationRepo.findUnreadByTitle(
      payload.orgId,
      org.ownerId,
      "plan_limit_reached",
      title,
    );
    if (pending) return;

    await notify(payload.orgId, "plan_limit_reached", [org.ownerId], {
      title,
      body: `${org.name} has used ${payload.used} of ${payload.limit} ${RESOURCE_LABELS[payload.resource]} on the ${org.plan} plan`,
      href: await settingsHref(payload.orgId, "billing"),
      // Whoever tried, the owner is told — even when it was the owner.
      actorId: null,
    });
  });
}

registerFanOut();
