import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as ns from "@/server/services/notification-service";
import * as usageService from "@/server/services/usage-service";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

const list = (t: any, role: string, extra: any = {}) =>
  ns.listNotifications(t.actors[role], { orgId: t.org.id, recipientId: t.userIds[role], unreadOnly: false, limit: 100, cursor: null, ...extra });

describe("scratch", () => {
  it("flows", async () => {
    const t = await createTenant("scr", "free");
    const issue = await issueService.createIssue(t.actors.member, { ...issueInput(t.org.id, t.project.id, { title: "Hello there" }), assigneeId: t.userIds.admin } as any);
    let p = await list(t, "admin");
    console.log(p.items.map((n) => [n.kind, n.href]));
    await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: issue.id, status: "done" } as any);
    p = await list(t, "admin");
    console.log(p.items.map((n) => [n.kind, n.href]));
    await expect(list(t, "member", { recipientId: t.userIds.admin })).rejects.toThrow();
    await expect(ns.markRead(t.actors.owner, { orgId: t.org.id, notificationId: p.items[0]!.id })).rejects.toThrow();
    // limits
    for (let i = 0; i < 4; i++) {
      await projectService.createProject(t.actors.member, { orgId: t.org.id, name: `P ${i}`, key: "", visibility: "private", leadId: null, description: null } as any).catch((e) => console.log("refused", e.message));
    }
    let o = await list(t, "owner");
    console.log(o.items.map((n) => [n.kind, n.title, n.href]));
    await ns.markAllRead(t.actors.owner, t.org.id);
    await projectService.createProject(t.actors.owner, { orgId: t.org.id, name: `P x`, key: "", visibility: "private", leadId: null, description: null } as any).catch(() => {});
    o = await list(t, "owner", { unreadOnly: true });
    console.log(o.items.map((n) => [n.kind, n.title]));
    await usageService.recomputeUsage(t.org.id);
    expect((await list(t, "owner", { unreadOnly: true })).total).toBe(1);
    expect((await list(t, "admin", { unreadOnly: true })).total).toBe(2);
    // in-app off
    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: t.userIds.admin, kind: "issue_assigned", inApp: false, email: true, digestOnly: false });
    await issueService.assignIssue(t.actors.member, { orgId: t.org.id, issueId: issue.id, assigneeId: t.userIds.admin });
    expect((await list(t, "admin")).total).toBe(2);
    // paging
    for (let i = 0; i < 30; i++) await ns.notify(t.org.id, "comment_created", [t.userIds.viewer], { title: `n${i}`, body: "", href: "/x", actorId: null });
    const seen = new Set<string>(); let cursor: string | null = null; let pages = 0;
    do { const pg: any = await list(t, "viewer", { limit: 7, cursor }); pg.items.forEach((n: any) => seen.add(n.id)); cursor = pg.nextCursor; pages++; } while (cursor);
    console.log("seen", seen.size, pages);
  });
});
EOF
